import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"资源选择参数","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"guide/cli/resource.md","filePath":"guide/cli/resource.md"}`),a={name:`guide/cli/resource.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="资源选择参数" tabindex="-1">资源选择参数 <a class="header-anchor" href="#资源选择参数" aria-label="Permalink to “资源选择参数”">​</a></h1><p>这里有一些参数专用于资源选择，你可以告诉我你需要哪些资源，比如弹幕、音频、视频等等。</p><h2 id="仅下载视频流" tabindex="-1">仅下载视频流 <a class="header-anchor" href="#仅下载视频流" aria-label="Permalink to “仅下载视频流”">​</a></h2><ul><li>参数 <code>--video-only</code></li><li>默认值 <code>False</code></li></ul><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>这里「仅下载视频流」是指视频中音视频流仅选择视频流，而不是仅仅下载视频而不下载弹幕字幕等资源，如果需要取消字幕等资源下载，请额外使用 <code>--no-danmaku</code> 等参数。</p><p>「仅下载音频流」也是同样的。</p></div><h2 id="仅下载音频流" tabindex="-1">仅下载音频流 <a class="header-anchor" href="#仅下载音频流" aria-label="Permalink to “仅下载音频流”">​</a></h2><ul><li>参数 <code>--audio-only</code></li><li>默认值 <code>False</code></li></ul><p>仅下载其中的音频流，保存为 <code>.m4a</code> 文件。</p><h2 id="不生成弹幕文件" tabindex="-1">不生成弹幕文件 <a class="header-anchor" href="#不生成弹幕文件" aria-label="Permalink to “不生成弹幕文件”">​</a></h2><ul><li>参数 <code>--no-danmaku</code></li><li>默认值 <code>False</code></li></ul><h2 id="仅生成弹幕文件" tabindex="-1">仅生成弹幕文件 <a class="header-anchor" href="#仅生成弹幕文件" aria-label="Permalink to “仅生成弹幕文件”">​</a></h2><ul><li>参数 <code>--danmaku-only</code></li><li>默认值 <code>False</code></li></ul><h2 id="不生成字幕文件" tabindex="-1">不生成字幕文件 <a class="header-anchor" href="#不生成字幕文件" aria-label="Permalink to “不生成字幕文件”">​</a></h2><ul><li>参数 <code>--no-subtitle</code></li><li>默认值 <code>False</code></li></ul><h2 id="仅生成字幕文件" tabindex="-1">仅生成字幕文件 <a class="header-anchor" href="#仅生成字幕文件" aria-label="Permalink to “仅生成字幕文件”">​</a></h2><ul><li>参数 <code>--subtitle-only</code></li><li>默认值 <code>False</code></li></ul><h2 id="选择字幕语言" tabindex="-1">选择字幕语言 <a class="header-anchor" href="#选择字幕语言" aria-label="Permalink to “选择字幕语言”">​</a></h2><ul><li>参数 <code>--subtitle-languages</code></li><li>默认值 <code>all</code>（下载所有可用字幕）</li></ul><p>使用逗号分隔语言代码，例如 <code>zh</code> 仅选择中文，<code>zh,en</code> 选择中文和英文。常用语言代码如下：</p><ul><li><code>zh</code>：中文</li><li><code>en</code>：英文</li><li><code>ja</code>：日文</li><li><code>ko</code>：韩文</li><li><code>es</code>：西班牙文</li><li><code>pt</code>：葡萄牙文</li><li><code>fr</code>：法文</li><li><code>de</code>：德文</li><li><code>ru</code>：俄文</li></ul><p>匹配不区分大小写，并包含地区、文字及 AI 变体：例如 <code>zh</code> 包含 <code>zh-CN</code>、<code>zh-Hans</code>、<code>zh-Hant</code>、<code>ai-zh</code>，<code>en</code> 包含 <code>en-US</code>、<code>ai-en</code>。指定更具体的代码可缩小范围，例如 <code>zh-Hans</code> 选择简体中文，<code>ai-zh</code> 仅选择自动生成的中文字幕。</p><h2 id="生成媒体元数据文件" tabindex="-1">生成媒体元数据文件 <a class="header-anchor" href="#生成媒体元数据文件" aria-label="Permalink to “生成媒体元数据文件”">​</a></h2><ul><li>参数 <code>--with-metadata</code></li><li>默认值 <code>False</code></li></ul><p>目前媒体元数据生成尚在试验阶段，可能提取出的信息并不完整。</p><h2 id="仅生成媒体元数据文件" tabindex="-1">仅生成媒体元数据文件 <a class="header-anchor" href="#仅生成媒体元数据文件" aria-label="Permalink to “仅生成媒体元数据文件”">​</a></h2><ul><li>参数 <code>--metadata-only</code></li><li>默认值 <code>False</code></li></ul><h2 id="不生成视频封面" tabindex="-1">不生成视频封面 <a class="header-anchor" href="#不生成视频封面" aria-label="Permalink to “不生成视频封面”">​</a></h2><ul><li>参数 <code>--no-cover</code></li><li>默认值 <code>False</code></li></ul><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>当前仅支持为包含视频流的视频生成封面。</p></div><h2 id="生成视频流封面时单独保存封面" tabindex="-1">生成视频流封面时单独保存封面 <a class="header-anchor" href="#生成视频流封面时单独保存封面" aria-label="Permalink to “生成视频流封面时单独保存封面”">​</a></h2><ul><li>参数 <code>--save-cover</code></li><li>默认值 <code>False</code></li></ul><h2 id="仅生成视频封面" tabindex="-1">仅生成视频封面 <a class="header-anchor" href="#仅生成视频封面" aria-label="Permalink to “仅生成视频封面”">​</a></h2><ul><li>参数 <code>--cover-only</code></li><li>默认值 <code>False</code></li></ul><h2 id="不生成章节信息" tabindex="-1">不生成章节信息 <a class="header-anchor" href="#不生成章节信息" aria-label="Permalink to “不生成章节信息”">​</a></h2><ul><li>参数 <code>--no-chapter-info</code></li><li>默认值 <code>False</code></li></ul><p>不生成章节信息，包含 MetaData 和嵌入视频流的章节信息。</p><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to “配置项”">​</a></h2><p>与命令行界面完全不同，配置文件可以直接表明你要下载的资源类型，比如：</p><div class="vp-code-block-title"><div class="vp-code-block-title-bar"><span class="vp-code-block-title-text" data-title="yutto.toml">yutto.toml</span></div><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">require_audio = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">require_subtitle = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">require_danmaku = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div></div><p>如上配置表明了你不需要音频、字幕和弹幕资源。</p><p>具体配置项如下：</p><h3 id="是否需要视频流" tabindex="-1">是否需要视频流 <a class="header-anchor" href="#是否需要视频流" aria-label="Permalink to “是否需要视频流”">​</a></h3><ul><li>配置项 <code>resource.video_only</code></li><li>默认值 <code>True</code></li></ul><h3 id="是否需要音频流" tabindex="-1">是否需要音频流 <a class="header-anchor" href="#是否需要音频流" aria-label="Permalink to “是否需要音频流”">​</a></h3><ul><li>配置项 <code>resource.require_audio</code></li><li>默认值 <code>True</code></li></ul><h3 id="是否需要弹幕" tabindex="-1">是否需要弹幕 <a class="header-anchor" href="#是否需要弹幕" aria-label="Permalink to “是否需要弹幕”">​</a></h3><ul><li>配置项 <code>resource.require_danmaku</code></li><li>默认值 <code>True</code></li></ul><h3 id="是否需要字幕" tabindex="-1">是否需要字幕 <a class="header-anchor" href="#是否需要字幕" aria-label="Permalink to “是否需要字幕”">​</a></h3><ul><li>配置项 <code>resource.require_subtitle</code></li><li>默认值 <code>True</code></li></ul><h3 id="字幕语言选择" tabindex="-1">字幕语言选择 <a class="header-anchor" href="#字幕语言选择" aria-label="Permalink to “字幕语言选择”">​</a></h3><ul><li>配置项 <code>resource.subtitle_languages</code></li><li>默认值 <code>None</code>（下载所有可用字幕）</li></ul><p>空数组 <code>[]</code> 表示不选择任何字幕。</p><h3 id="是否需要媒体元数据" tabindex="-1">是否需要媒体元数据 <a class="header-anchor" href="#是否需要媒体元数据" aria-label="Permalink to “是否需要媒体元数据”">​</a></h3><ul><li>配置项 <code>resource.require_metadata</code></li><li>默认值 <code>False</code></li></ul><h3 id="是否需要视频封面" tabindex="-1">是否需要视频封面 <a class="header-anchor" href="#是否需要视频封面" aria-label="Permalink to “是否需要视频封面”">​</a></h3><ul><li>配置项 <code>resource.require_cover</code></li><li>默认值 <code>True</code></li></ul><h3 id="是否需要章节信息" tabindex="-1">是否需要章节信息 <a class="header-anchor" href="#是否需要章节信息" aria-label="Permalink to “是否需要章节信息”">​</a></h3><ul><li>配置项 <code>resource.require_chapter_info</code></li><li>默认值 <code>True</code></li></ul><h3 id="生成视频流封面时单独保存封面-1" tabindex="-1">生成视频流封面时单独保存封面 <a class="header-anchor" href="#生成视频流封面时单独保存封面-1" aria-label="Permalink to “生成视频流封面时单独保存封面”">​</a></h3><ul><li>配置项 <code>resource.save_cover</code></li><li>默认值 <code>False</code></li></ul>`,60)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};